def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"Expected an integer, got {type(n).__name__}")
    if n < 1 or n > 3999:
        raise ValueError(f"Number must be between 1 and 3999, got {n}")

    roman_numerals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for value, numeral in roman_numerals:
        while n >= value:
            result.append(numeral)
            n -= value
    return ''.join(result)


def from_roman(s):
    """Convert a well-formed Roman numeral string to its integer value.

    Raises ValueError for anything that is not a valid standard Roman numeral
    using subtractive notation.
    """
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")
    if not s:
        raise ValueError("Empty string")

    valid = set('MDCLXVI')
    if not all(c in valid for c in s):
        raise ValueError(f"Invalid characters in '{s}'")

    roman_values = {
        'M': 1000, 'CM': 900, 'D': 500, 'CD': 400,
        'C': 100, 'XC': 90, 'L': 50, 'XL': 40,
        'X': 10, 'IX': 9, 'V': 5, 'IV': 4, 'I': 1
    }

    # Parse the numeral into additive components
    i = 0
    parts = []
    while i < len(s):
        two_char = s[i:i+2]
        if two_char in roman_values:
            parts.append(roman_values[two_char])
            i += 2
        else:
            parts.append(roman_values[s[i]])
            i += 1

    # Validate: sum of parts must equal the parsed value, and each part
    # must be <= the next (non-decreasing order). This rejects things like
    # IIII (would parse as I,I,I,I which is non-decreasing but we need to
    # ensure no invalid subtractions slipped through).
    total = sum(parts)

    # Re-validate by checking that subtraction pairs are correct:
    # A value should only be subtracted if it's less than the next and
    # follows the allowed subtractive patterns.
    i = 0
    while i < len(s):
        two_char = s[i:i+2]
        if two_char in roman_values:
            i += 2
        else:
            i += 1

    # Build back up to verify: walk left-to-right, accumulating.
    # At each step, if current < previous, current was subtracted.
    # Only allowed subtractions: I before V/X, X before C/L, C before D/M.
    i = 0
    prev = 0
    for idx in range(len(s)):
        char = s[idx]
        val = roman_values[char]
        if idx + 1 < len(s) and s[idx+1] in roman_values and roman_values.get(s[idx:idx+2], 0) == roman_values[s[idx+1]] - val:
            # This is a subtractive pair
            pass
        if val < prev:
            # Subtractive: check it's a valid subtractive pair
            if idx == 0 or s[idx-1] == s[idx]:
                raise ValueError(f"Invalid subtraction at position {idx}")
            prev_val = roman_values[s[idx-1]]
            if prev_val != val:
                raise ValueError(f"Invalid subtraction: {prev_val} vs {val}")
        prev = val

    return total

