_ROMAN_VALUES = {
    'M': 1000, 'D': 500, 'C': 100, 'L': 50,
    'X': 10, 'V': 5, 'I': 1,
}

# Allowed subtractive pairs: (smaller, larger)
_SUBTRACTIVE_PAIRS = {('I', 'V'), ('I', 'X'), ('X', 'L'), ('X', 'C'), ('C', 'D'), ('C', 'M')}


def from_roman(s):
    """Convert a well-formed Roman numeral string to its integer value.

    Raises ValueError for anything that is not a valid standard Roman numeral
    using subtractive notation.
    """
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")
    if not s:
        raise ValueError("Empty string")

    # All characters must be valid Roman numeral symbols
    for c in s:
        if c not in _ROMAN_VALUES:
            raise ValueError(f"Invalid character '{c}' in '{s}'")

    values = [_ROMAN_VALUES[c] for c in s]
    total = sum(values)

    i = 0
    while i < len(values):
        # Check if this position starts a subtractive pair
        if i + 1 < len(values) and values[i] < values[i + 1]:
            # Subtract the current value (it's being subtracted)
            total -= 2 * values[i]
            i += 1
            # Validate the subtractive pair is allowed
            char_pair = (s[i - 1], s[i])
            if char_pair not in _SUBTRACTIVE_PAIRS:
                raise ValueError(f"Invalid subtractive pair {''.join(char_pair)} in '{s}'")
        i += 1

    # Verify round-trip: re-encode and compare
    if to_roman(total) != s:
        raise ValueError(f"'{s}' is not a well-formed Roman numeral (round-trip failed)")

    return total

import pytest
from roman import to_roman, from_roman


class TestToRoman:
    """Tests for to_roman(n)."""

    def test_one(self):
        assert to_roman(1) == "I"

    def test_two(self):
        assert to_roman(2) == "II"

    def test_three(self):
        assert to_roman(3) == "III"

    def test_four(self):
        assert to_roman(4) == "IV"

    def test_five(self):
        assert to_roman(5) == "V"

    def test_six(self):
        assert to_roman(6) == "VI"

    def test_nine(self):
        assert to_roman(9) == "IX"

    def test_ten(self):
        assert to_roman(10) == "X"

    def test_forty(self):
        assert to_roman(40) == "XL"

    def test_fifty(self):
        assert to_roman(50) == "L"

    def test_ninety(self):
        assert to_roman(90) == "XC"

    def test_hundred(self):
        assert to_roman(100) == "C"

    def test_four_hundred(self):
        assert to_roman(400) == "CD"

    def test_five_hundred(self):
        assert to_roman(500) == "D"

    def test_nine_hundred(self):
        assert to_roman(900) == "CM"

    def test_thousand(self):
        assert to_roman(1000) == "M"

    def test_two_thousand(self):
        assert to_roman(2000) == "MM"

    def test_three_thousand(self):
        assert to_roman(3000) == "MMM"

    def test_max(self):
        assert to_roman(3999) == "MMMCMXCIX"

    @pytest.mark.parametrize("n", [0, -1, -100, 4000, 10000])
    def test_out_of_range(self, n):
        with pytest.raises(ValueError):
            to_roman(n)

    @pytest.mark.parametrize("n", [1.5, 3.14, 0.0, float('inf'), float('nan')])
    def test_non_integer_float(self, n):
        with pytest.raises(ValueError):
            to_roman(n)

    @pytest.mark.parametrize("n", ["1", True, None, (1,), [1], {"a": 1}])
    def test_non_integer_types(self, n):
        with pytest.raises(ValueError):
            to_roman(n)

    def test_boolean_rejected(self):
        with pytest.raises(ValueError):
            to_roman(True)
        with pytest.raises(ValueError):
            to_roman(False)


class TestFromRoman:
    """Tests for from_roman(s)."""

    def test_i(self):
        assert from_roman("I") == 1

    def test_ii(self):
        assert from_roman("II") == 2

    def test_iii(self):
        assert from_roman("III") == 3

    def test_iv(self):
        assert from_roman("IV") == 4

    def test_v(self):
        assert from_roman("V") == 5

    def test_vi(self):
        assert from_roman("VI") == 6

    def test_ix(self):
        assert from_roman("IX") == 9

    def test_x(self):
        assert from_roman("X") == 10

    def test_xl(self):
        assert from_roman("XL") == 40

    def test_l(self):
        assert from_roman("L") == 50

    def test_xc(self):
        assert from_roman("XC") == 90

    def test_c(self):
        assert from_roman("C") == 100

    def test_cd(self):
        assert from_roman("CD") == 400

    def test_d(self):
        assert from_roman("D") == 500

    def test_cm(self):
        assert from_roman("CM") == 900

    def test_m(self):
        assert from_roman("M") == 1000

    def test_mmmcmxcix(self):
        assert from_roman("MMMCMXCIX") == 3999

    @pytest.mark.parametrize("s", ["", " ", "banana", "ABC", "foo"])
    def test_invalid_characters(self, s):
        with pytest.raises(ValueError):
            from_roman(s)

    @pytest.mark.parametrize("s", ["IIII", "VV", "LL", "DD", "MMMM"])
    def test_repeated_excess(self, s):
        with pytest.raises(ValueError):
            from_roman(s)

    @pytest.mark.parametrize("s", ["IC", "XM", "IL", "XD", "VM", "IM"])
    def test_invalid_subtractive_pairs(self, s):
        with pytest.raises(ValueError):
            from_roman(s)

    @pytest.mark.parametrize("s", ["AB", "123", "!@#$"])
    def test_non_roman_input(self, s):
        with pytest.raises(ValueError):
            from_roman(s)

    @pytest.mark.parametrize("s", [None, 42, 3.14, True, b"IV", 123])
    def test_non_string_input(self, s):
        with pytest.raises(ValueError):
            from_roman(s)

    def test_lower_case_rejected(self):
        with pytest.raises(ValueError):
            from_roman("iv")
        with pytest.raises(ValueError):
            from_roman("mcmxcix")

    def test_double_subtraction(self):
        # e.g. IIX is not valid (should be VIII)
        with pytest.raises(ValueError):
            from_roman("IIX")

    def test_wrong_order(self):
        # e.g. IM = should be MCMXCIX, not a direct subtraction
        with pytest.raises(ValueError):
            from_roman("IM")


class TestRoundTrip:
    """Tests that from_roman(to_roman(n)) == n for all n in 1..3999."""

    @pytest.mark.parametrize("n", list(range(1, 4000)))
    def test_roundtrip_all(self, n):
        assert from_roman(to_roman(n)) == n

    @pytest.mark.parametrize("n", [0, -1, 4000, 10000])
    def test_to_roman_raises(self, n):
        with pytest.raises(ValueError):
            to_roman(n)
